"""fcp/dosage_judge_audit.py -- audit of the v1 3B greedy judge from the committed
fcp/dosage/responses_judged.parquet only (step J2). Writes fcp/results/dosage/judge_audit.md.

Usage: python fcp/dosage_judge_audit.py
"""
from pathlib import Path

import numpy as np
import pandas as pd

ROOT = Path(__file__).resolve().parent.parent
d = pd.read_parquet(ROOT / "fcp/dosage/responses_judged.parquet")
s = d.judge_score
num = d[s.notna()]
out = ["# Dosage v1 judge audit (Qwen2.5-3B-Instruct, greedy)", "",
       "Generated by `fcp/dosage_judge_audit.py` from the committed `fcp/dosage/responses_judged.parquet` only "
       f"({len(d)} responses: 20 conditions x 8 questions x 10 samples, 200-token cap).", "",
       "## Status counts", "", d.judge_status.value_counts().rename("n").to_frame().to_markdown(), "",
       "## Score histogram (numeric scores)", ""]
bins = [-1, 9, 19, 29, 39, 49, 59, 69, 79, 84, 85, 89, 99, 100]
labels = ["0-9", "10-19", "20-29", "30-39", "40-49", "50-59", "60-69", "70-79", "80-84", "85", "86-89", "90-99", "100"]
h = pd.cut(num.judge_score, bins=bins, labels=labels).value_counts().reindex(labels)
out += [h.rename("n").to_frame().to_markdown(), "",
        f"**{int((s == 85).sum())} of {len(num)} numeric scores are exactly 85**; {int((s < 30).sum())} are below 30.", "",
        "## Share of scores at exactly 85, by condition", ""]
by = num.groupby("step").agg(n=("judge_score", "size"), share_85=("judge_score", lambda x: (x == 85).mean()),
                             mean=("judge_score", "mean"), n_below_30=("judge_score", lambda x: int((x < 30).sum())))
out += [by.round(3).to_markdown(), "", "## Mean score by question", "",
        num.groupby("question_id").judge_score.agg(["mean", "size"]).round(1).to_markdown(), "",
        "## The responses scored below 30, by condition and question", "",
        pd.crosstab(num[num.judge_score < 30].step, num[num.judge_score < 30].question_id).to_markdown(), ""]


def examples(df, title):
    lines = [f"## {title}", ""]
    for _, r in df.iterrows():
        txt = r.response.replace("\n", " ")[:400]
        lines += [f"- **{r.condition} / {r.question_id}** (score {r.judge_score:.0f}): {txt}", ""]
    return lines


out += examples(num[(num.step == 792) & (num.judge_score == 85)].sample(10, random_state=0),
                "10 random responses scored 85 at step 792")
out += examples(num[num.judge_score < 30].sample(10, random_state=0), "10 random responses scored below 30")
out += ["## Conclusions (cautious)", "",
        "- The 3B judge's output collapses onto 85 for most responses, so per-condition means move only "
        "through a small number of non-85 scores.",
        "- Hand labels (`fcp/results/dosage/judge_validation.md`) confirm the judge is unreliable at the EM "
        "threshold: kappa 0.14 against two human labellers, 25 false positives among 160 labelled items.",
        "- v1 results that depend on this judge should be treated as superseded by the weighted judges.", ""]
dst = ROOT / "fcp/results/dosage/judge_audit.md"
dst.write_text("\n".join(out))
print(f"wrote {dst}")
